{"command": "python3 <<'PY'
import subprocess, re
def has(ns, method):
    import subprocess
    p=subprocess.run(["/workspace/executable","-i", '{{ '+ns+'.'+method+' }}'], capture_output=True, text=True, cwd="/tmp", timeout=10)
    err=p.stderr
    out=p.stdout
    if 'can\'t evaluate field' in err or 'not defined' in err:
        return f"MISSING"
    elif p.returncode==0:
        return f"EXISTS out={out[:60]!r}"
    else:
        if 'wrong number of args' in err or 'error calling' in err:
            # extract error
            return f"EXISTS err={err[err.find('error calling'):err.find('error calling')+200]!r}"
        return f"UNKNOWN rc={p.returncode} err={err[:200]!r}"

for fname in ["base64","coll","conv","crypto","data","env","file","filepath","gcp","math","net","path","random","regexp","semver","sockaddr","strings","test","time","tmpl","uuid","aws"]:
    text=open(f"docs/content/functions/{fname}.md").read() if fname not in ["aws"] else open("docs/content/functions/aws.md").read()
    # different patterns
    if fname=="data":
        methods=re.findall(r'## `data\.(\w+)`', text)
    elif fname in ["base64","coll","conv","crypto","env","file","filepath","math","net","path","random","regexp","semver","sockaddr","strings","test","time","tmpl","uuid"]:
        # generic
        methods=re.findall(r'## `\w+\.(\w+)`', text)
    elif fname=="gcp":
        methods=re.findall(r'## `gcp\.(\w+)`', text)
    elif fname=="aws":
        methods=re.findall(r'## `aws\.(\w+)`', text)
    else:
        methods=[]
    print(f"== {fname} {methods} ==")
    for m in methods:
        print(f"  {fname}.{m:25} {has(fname,m)}")
PY"}

