// Package funcs implements gomplate namespaces
package funcs

import (
	"fmt"
	"reflect"
	"sort"
)

func toString(v any) string {
	if v == nil {
		return ""
	}
	switch s := v.(type) {
	case string:
		return s
	case []byte:
		return string(s)
	case fmt.Stringer:
		return s.String()
	default:
		return fmt.Sprintf("%v", v)
	}
}

func toInt64(v any) (int64, error) {
	switch n := v.(type) {
	case int:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int64:
		return n, nil
	case uint:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case string:
		// try parse float then int?
		var f float64
		_, err := fmt.Sscanf(n, "%g", &f)
		if err == nil {
			return int64(f), nil
		}
		return 0, fmt.Errorf("could not convert %q to int64", n)
	default:
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			return rv.Int(), nil
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return int64(rv.Uint()), nil
		case reflect.Float32, reflect.Float64:
			return int64(rv.Float()), nil
		case reflect.String:
			var f float64
			_, err := fmt.Sscanf(rv.String(), "%g", &f)
			if err == nil {
				return int64(f), nil
			}
		}
		return 0, fmt.Errorf("could not convert %v to int64", v)
	}
}

// helpers for sorting etc.
func sortedKeys(m map[string]any) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}
GO
