	"strconv"
)

type MathFuncs struct{}

func toFloat(v any) (float64, error) {
	switch n := v.(type) {
	case int:
		return float64(n), nil
	case int8:
		return float64(n), nil
	case int16:
		return float64(n), nil
	case int32:
		return float64(n), nil
	case int64:
		return float64(n), nil
	case uint:
		return float64(n), nil
	case uint8:
		return float64(n), nil
	case uint16:
		return float64(n), nil
	case uint32:
		return float64(n), nil
	case uint64:
		return float64(n), nil
	case float32:
		return float64(n), nil
	case float64:
		return n, nil
	case string:
		f, err := strconv.ParseFloat(n, 64)
		if err != nil {
			return 0, fmt.Errorf("could not convert %q to int64: %v", n, err)
		}
		return f, nil
	default:
		// try via fmt?
		s := fmt.Sprintf("%v", v)
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, fmt.Errorf("could not convert %q to int64: %v", s, err)
		}
		return f, nil
	}
}

func isFloatVal(v any) bool {
	switch v.(type) {
	case float32, float64:
		return true
	case string:
		s := v.(string)
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return false
		}
		// check if contains . or e?
		_ = f
		// if string contains . or e/E, consider float? But original IsFloat? Need to check: IsFloat 1 vs 1.0?
		// For now, if parse succeeds and string contains . or e, true else false? But what about "1.0" vs "1"? Let's assume.
		for _, c := range s {
			if c == '.' || c == 'e' || c == 'E' {
				return true
			}
		}
		return false
	default:
		return false
	}
}

func mathAdd(args ...any) (any, error) {
	if len(args) == 0 {
		return int64(0), nil
	}
	// check if any float?
	hasFloat := false
	for _, a := range args {
		if isFloatVal(a) {
			hasFloat = true
			break
		}
		// also if any float type?
		switch a.(type) {
		case float32, float64:
			hasFloat = true
		}
		// if string that parses as float with .?
		if s, ok := a.(string); ok {
			if _, err := strconv.ParseFloat(s, 64); err == nil {
				// check if float?
				if containsFloatChars(s) {
					hasFloat = true
				}
			}
		}
	}
	if hasFloat {
		var sum float64
		for _, a := range args {
			f, err := toFloat(a)
			if err != nil {
				return nil, fmt.Errorf("expected number inputs: %v", err)
			}
			sum += f
		}
		// if sum is whole number, should we return int? Original math.Add 1.5+2 => 3.5 float. Add 1+2 => 6 int. With floats, return float64. Good.
		return sum, nil
	}
	var sum int64
	for _, a := range args {
		// try int conversion via float then int?
		f, err := toFloat(a)
		if err != nil {
			return nil, fmt.Errorf("expected number inputs: %v", err)
		}
		// check if f is not integer? Actually for int path, we already determined no floats, so f should be integer.
		sum += int64(f)
	}
	return sum, nil
}

func containsFloatChars(s string) bool {
	for _, c := range s {
		if c == '.' || c == 'e' || c == 'E' {
			return true
		}
	}
	return false
}

func (f *MathFuncs) Add(args ...any) (any, error) {
	if len(args) == 0 {
		return int64(0), nil
	}
	return mathAdd(args...)
}

func (f *MathFuncs) Mul(args ...any) (any, error) {
	if len(args) == 0 {
		return int64(1), nil
	}
