func marshalCUE(v any) (string, error) {
	// simple: for map, "{\n\tk: value\n}" sorted, for slice? etc.
	switch x := v.(type) {
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var b strings.Builder
		b.WriteString("{\n")
		for _, k := range keys {
			valStr := cueValue(x[k])
			b.WriteString("\t" + k + ": " + valStr + "\n")
		}
		b.WriteString("}")
		return b.String(), nil
	default:
		// fallback to JSON?
		b, err := json.MarshalIndent(v, "", "\t")
		if err != nil {
			return "", err
		}
		return string(b), nil
	}
}

func cueValue(v any) string {
	switch x := v.(type) {
	case string:
		return strconv.Quote(x)
	case int, int64, float64, bool:
		return fmt.Sprintf("%v", x)
	case map[string]any:
		s, _ := marshalCUE(x)
		return s
	case []any:
		var parts []string
		for _, e := range x {
			parts = append(parts, cueValue(e))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	default:
		return fmt.Sprintf("%v", v)
	}
}

func reflectValue(v any) reflect.Value {
	// helper to avoid import? Need reflect
	return reflect.ValueOf(v)
}
