			if save >= len(p.lines) {
				out = append(out, nil)
			} else {
				nextIndent := countIndent(p.lines[save])
				if nextIndent > indent {
					nested, err := p.parseBlock(nextIndent)
					if err != nil {
						return nil, err
					}
					out = append(out, nested)
				} else {
					out = append(out, nil)
				}
			}
		} else {
			// content could be map inline? e.g., "- a: 1"? Handle: if content is map line, need to parse as map with first entry + following indented lines?
			if isMapLine(content) {
				// First map entry from content, plus following lines at greater indent as part of same map?
