					nt := strings.TrimSpace(nl)
					if nt == "" || strings.HasPrefix(nt, "#") {
						p.pos++
						continue
					}
					ni := countIndent(nl)
					if ni <= indent {
						break
					}
					// if line is list item, break (next item)
					if strings.HasPrefix(nt, "- ") || nt == "-" {
						break
