					}
					kk, vv := splitMapLine(nt)
					kk = stripQuotes(strings.TrimSpace(kk))
					vv = strings.TrimSpace(stripComment(vv))
					p.pos++
					if vv == "" {
						// nested?
						save2 := p.pos
						for save2 < len(p.lines) {
							nl2 := p.lines[save2]
							nt2 := strings.TrimSpace(nl2)
							if nt2 == "" || strings.HasPrefix(nt2, "#") {
