func splitMapLine(s string) (string, string) {
	inSingle, inDouble := false, false
	for i, c := range s {
		if c == '\'' && !inDouble {
			inSingle = !inSingle
		} else if c == '"' && !inSingle {
			if i > 0 && s[i-1] == '\\' {
				continue
			}
			inDouble = !inDouble
		} else if c == ':' && !inSingle && !inDouble {
			if i+1 >= len(s) || s[i+1] == ' ' || s[i+1] == '\t' {
				return s[:i], s[i+1:]
			}
		}
	}
	// no colon? Return whole as key?
	return s, ""
}

func stripQuotes(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			inner := s[1 : len(s)-1]
			if s[0] == '"' {
				// unescape?
				inner = strings.ReplaceAll(inner, `\"`, `"`)
				inner = strings.ReplaceAll(inner, `\\`, `\`)
				inner = strings.ReplaceAll(inner, `\n`, "\n")
				inner = strings.ReplaceAll(inner, `\t`, "\t")
			}
			return inner
		}
	}
	return s
}

func stripComment(s string) string {
	inSingle, inDouble := false, false
	for i, c := range s {
		if c == '\'' && !inDouble {
			inSingle = !inSingle
		} else if c == '"' && !inSingle {
			if i > 0 && s[i-1] == '\\' {
				continue
			}
			inDouble = !inDouble
		} else if c == '#' && !inSingle && !inDouble {
			// check preceding space?
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return strings.TrimSpace(s[:i])
			}
		}
	}
	return s
}

func parseYAMLScalar(s string) any {
	s = strings.TrimSpace(s)
	if s == "" || s == "null" || s == "~" {
		return nil
	}
	if s == "true" || s == "True" || s == "TRUE" {
		return true
	}
	if s == "false" || s == "False" || s == "FALSE" {
		return false
	}
	// quoted?
	if len(s) >= 2 && ((s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'')) {
		return stripQuotes(s)
	}
	// flow style? Handle inline arrays/maps? e.g., "[1, 2]" or "{a: 1}"? For simplicity, if starts with [ and ends with ], parse as list?
