	}
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		inner := s[1 : len(s)-1]
		if strings.TrimSpace(inner) == "" {
			return map[string]any{}
		}
		parts := splitFlow(inner)
		m := make(map[string]any)
