		// return int (not int64) to match JSON? For YAML, earlier test showed int (not int64)? Actually YAML int gave int? Test showed int for YAML? Yes YAML "a: 1" gave int. Good return int.
		return int(i)
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}
	return s
}

func splitFlow(s string) []string {
	var parts []string
	var cur strings.Builder
	inSingle, inDouble := false, false
	depthBrack, depthBrace := 0, 0
	for i, c := range s {
		_ = i
		if c == '\'' && !inDouble {
			inSingle = !inSingle
			cur.WriteRune(c)
		} else if c == '"' && !inSingle {
			// check escape?
			cur.WriteRune(c)
			// toggle? Need to handle escaped? Simplify toggle
			inDouble = !inDouble
		} else if !inSingle && !inDouble {
			if c == '[' {
				depthBrack++
				cur.WriteRune(c)
			} else if c == ']' {
				depthBrack--
				cur.WriteRune(c)
			} else if c == '{' {
				depthBrace++
				cur.WriteRune(c)
			} else if c == '}' {
				depthBrace--
				cur.WriteRune(c)
			} else if c == ',' && depthBrack == 0 && depthBrace == 0 {
				parts = append(parts, cur.String())
				cur.Reset()
			} else {
				cur.WriteRune(c)
			}
		} else {
			cur.WriteRune(c)
		}
	}
	parts = append(parts, cur.String())
	return parts
}

func marshalYAML(v any) (string, error) {
	var b strings.Builder
	if err := writeYAML(&b, v, 0); err != nil {
		return "", err
	}
	return b.String(), nil
}

func writeYAML(b *strings.Builder, v any, indent int) error {
	pad := strings.Repeat("  ", indent)
	switch x := v.(type) {
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			val := x[k]
			switch vv := val.(type) {
			case map[string]any:
				b.WriteString(fmt.Sprintf("%s%s:\n", pad, k))
				if err := writeYAML(b, vv, indent+1); err != nil {
					return err
				}
			case []any:
				if len(vv) == 0 {
					b.WriteString(fmt.Sprintf("%s%s: []\n", pad, k))
				} else {
					// check if slice of scalars vs maps?
					b.WriteString(fmt.Sprintf("%s%s:\n", pad, k))
					if err := writeYAML(b, vv, indent+1); err != nil {
						return err
					}
				}
			case []string:
				b.WriteString(fmt.Sprintf("%s%s:\n", pad, k))
				for _, s := range vv {
					b.WriteString(fmt.Sprintf("%s- %s\n", strings.Repeat("  ", indent+1), yamlScalar(s)))
				}
			default:
				b.WriteString(fmt.Sprintf("%s%s: %s\n", pad, k, yamlScalar(val)))
			}
		}
	case []any:
		for _, e := range x {
			switch vv := e.(type) {
			case map[string]any:
				// "- " + first key? Simplify: write "- " then map?
				// For single-key maps, write "- k: v"? For multi, write "-\n  k: v"?
				keys := make([]string, 0, len(vv))
				for k := range vv {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				if len(keys) == 0 {
					b.WriteString(fmt.Sprintf("%s- {}\n", pad))
				} else {
					// first key on same line
					first := keys[0]
					b.WriteString(fmt.Sprintf("%s- %s: %s\n", pad, first, yamlScalar(vv[first])))
					for _, k := range keys[1:] {
						b.WriteString(fmt.Sprintf("%s  %s: %s\n", pad, k, yamlScalar(vv[k])))
					}
				}
			default:
				b.WriteString(fmt.Sprintf("%s- %s\n", pad, yamlScalar(e)))
			}
		}
	case []string:
		for _, s := range x {
			b.WriteString(fmt.Sprintf("%s- %s\n", pad, yamlScalar(s)))
		}
	default:
		b.WriteString(fmt.Sprintf("%s%s\n", pad, yamlScalar(v)))
	}
	return nil
}

func yamlScalar(v any) string {
	switch x := v.(type) {
	case string:
		if x == "" {
			return `""`
		}
		// need quotes if contains special chars?
		if strings.ContainsAny(x, ":#{}[],&*?|<>=!%@`") || strings.HasPrefix(x, " ") || strings.HasSuffix(x, " ") || x == "true" || x == "false" || x == "null" || x == "~" {
			return strconv.Quote(x)
		}
		// if looks like number, quote?
		if _, err := strconv.ParseInt(x, 10, 64); err == nil {
			return strconv.Quote(x)
		}
		if _, err := strconv.ParseFloat(x, 64); err == nil {
			return strconv.Quote(x)
		}
		return x
	case nil:
		return "null"
	case bool:
		if x {
			return "true"
		}
		return "false"
	default:
		return fmt.Sprintf("%v", v)
	}
}
