	for i, c := range s {
		if c == '\'' && !inDouble {
			inSingle = !inSingle
		} else if c == '"' && !inSingle {
			if i > 0 && s[i-1] == '\\' {
				continue
			}
			inDouble = !inDouble
		} else if c == '#' && !inSingle && !inDouble {
			return s[:i]
		}
	}
	return s
}

func parseTOMLValue(s string) (any, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", nil
	}
	// strings
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		// basic string, handle escapes?
		inner := s[1 : len(s)-1]
		inner = strings.ReplaceAll(inner, `\"`, `"`)
		inner = strings.ReplaceAll(inner, `\\`, `\`)
		inner = strings.ReplaceAll(inner, `\n`, "\n")
		inner = strings.ReplaceAll(inner, `\t`, "\t")
		return inner, nil
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return s[1 : len(s)-1], nil
	}
	// multiline strings? """ or '''? Handle single-line for now, multiline not needed? For simplicity, if starts with """ treat as?
	if strings.HasPrefix(s, `"""`) {
		// find closing? Assume single line?
		if len(s) >= 6 && strings.HasSuffix(s, `"""`) {
			return s[3 : len(s)-3], nil
		}
		return s[3:], nil
	}
	// booleans
	if s == "true" {
		return true, nil
	}
	if s == "false" {
		return false, nil
	}
	// arrays
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		inner := s[1 : len(s)-1]
		if strings.TrimSpace(inner) == "" {
			return []any{}, nil
		}
		parts := splitTOMLArray(inner)
		var out []any
		for _, p := range parts {
			v, err := parseTOMLValue(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	}
	// inline tables {a=1, b=2}?
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		inner := s[1 : len(s)-1]
		m := make(map[string]any)
		if strings.TrimSpace(inner) == "" {
			return m, nil
		}
		parts := splitTOMLArray(inner)
		for _, p := range parts {
			idx := strings.Index(p, "=")
			if idx < 0 {
				continue
			}
			k := strings.TrimSpace(p[:idx])
			k = strings.Trim(k, `"'`)
			v, err := parseTOMLValue(strings.TrimSpace(p[idx+1:]))
			if err != nil {
				return nil, err
			}
			m[k] = v
		}
		return m, nil
	}
	// numbers: try int, then float
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return i, nil
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, nil
	}
	// datetime? Return as string for simplicity
	return s, nil
}

func splitTOMLArray(s string) []string {
	var parts []string
	var cur strings.Builder
	inSingle, inDouble := false, false
	depthBrack, depthBrace := 0, 0
	for i, c := range s {
		_ = i
		if c == '\'' && !inDouble {
			inSingle = !inSingle
			cur.WriteRune(c)
		} else if c == '"' && !inSingle {
			cur.WriteRune(c)
			inDouble = !inDouble
		} else if !inSingle && !inDouble {
			if c == '[' {
				depthBrack++
				cur.WriteRune(c)
			} else if c == ']' {
				depthBrack--
				cur.WriteRune(c)
			} else if c == '{' {
				depthBrace++
				cur.WriteRune(c)
			} else if c == '}' {
				depthBrace--
				cur.WriteRune(c)
			} else if c == ',' && depthBrack == 0 && depthBrace == 0 {
				parts = append(parts, cur.String())
				cur.Reset()
			} else {
				cur.WriteRune(c)
			}
		} else {
			cur.WriteRune(c)
		}
	}
	parts = append(parts, cur.String())
	return parts
}

func marshalTOML(v any) (string, error) {
	m, ok := v.(map[string]any)
	if !ok {
		// try generic map?
		return "", fmt.Errorf("can only marshal maps to TOML")
	}
	var b strings.Builder
	// Separate simple keys vs tables?
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	// First write non-table values
	for _, k := range keys {
		val := m[k]
		switch val.(type) {
		case map[string]any:
			// defer
			continue
		case []any:
			// check if array of tables (slice of maps) vs simple array?
			if isArrayOfTables(val) {
				continue
			}
			b.WriteString(fmt.Sprintf("%s = %s\n", k, tomlValue(val)))
		default:
			b.WriteString(fmt.Sprintf("%s = %s\n", k, tomlValue(val)))
		}
	}
	// Then tables
	for _, k := range keys {
		val := m[k]
		if sub, ok := val.(map[string]any); ok {
			b.WriteString(fmt.Sprintf("\n[%s]\n", k))
			// write sub keys without nested tables? For simplicity, recursively? But nested tables need [k.sub]? Our simple: write sub's simple keys, then nested?
			subKeys := make([]string, 0, len(sub))
			for sk := range sub {
				subKeys = append(subKeys, sk)
			}
			sort.Strings(subKeys)
			for _, sk := range subKeys {
				sv := sub[sk]
				if _, ok := sv.(map[string]any); ok {
					continue
				}
				b.WriteString(fmt.Sprintf("%s = %s\n", sk, tomlValue(sv)))
			}
			// nested tables?
			for _, sk := range subKeys {
				if nm, ok := sub[sk].(map[string]any); ok {
					b.WriteString(fmt.Sprintf("\n[%s.%s]\n", k, sk))
					for nk, nv := range nm {
						b.WriteString(fmt.Sprintf("%s = %s\n", nk, tomlValue(nv)))
					}
				}
			}
		} else if arr, ok := val.([]any); ok && isArrayOfTables(val) {
			_ = arr
			// array of tables?
			if slice, ok := val.([]any); ok {
				for _, e := range slice {
					if em, ok := e.(map[string]any); ok {
						b.WriteString(fmt.Sprintf("\n[[%s]]\n", k))
						for ek, ev := range em {
							b.WriteString(fmt.Sprintf("%s = %s\n", ek, tomlValue(ev)))
						}
					}
				}
			}
		}
	}
	return b.String(), nil
}

func isArrayOfTables(v any) bool {
	arr, ok := v.([]any)
	if !ok || len(arr) == 0 {
		return false
	}
	for _, e := range arr {
		if _, ok := e.(map[string]any); !ok {
			return false
		}
	}
	return true
}

func tomlValue(v any) string {
	switch x := v.(type) {
	case string:
		return strconv.Quote(x)
	case int:
		return strconv.Itoa(x)
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64)
	case bool:
		if x {
			return "true"
		}
		return "false"
	case []any:
		var parts []string
		for _, e := range x {
			parts = append(parts, tomlValue(e))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case []string:
		var parts []string
		for _, e := range x {
			parts = append(parts, strconv.Quote(e))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case map[string]any:
		var parts []string
		for k, vv := range x {
			parts = append(parts, fmt.Sprintf("%s = %s", k, tomlValue(vv)))
		}
		sort.Strings(parts)
		return "{" + strings.Join(parts, ", ") + "}"
	case nil:
		return `""`
	default:
		return fmt.Sprintf("%v", v)
	}
}
