package funcs

import (
	"fmt"
	"strconv"
	"strings"
)

type SemverFuncs struct{}

type semver struct {
	Major, Minor, Patch int
	Prerelease string
	Build string
	Original string
}

func parseSemver(s string) (*semver, error) {
	orig := s
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "v") {
		s = s[1:]
	}
	// split build +
	build := ""
	if idx := strings.Index(s, "+"); idx >= 0 {
		build = s[idx+1:]
		s = s[:idx]
	}
	pre := ""
	if idx := strings.Index(s, "-"); idx >= 0 {
		pre = s[idx+1:]
		s = s[:idx]
	}
	parts := strings.Split(s, ".")
	if len(parts) != 3 {
		return nil, fmt.Errorf("invalid semver %q", orig)
	}
	maj, err := strconv.Atoi(parts[0])
	if err != nil {
		return nil, err
	}
	min, err := strconv.Atoi(parts[1])
	if err != nil {
		return nil, err
	}
	patch, err := strconv.Atoi(parts[2])
	if err != nil {
		// patch may contain pre? Already split, but handle?
		return nil, err
	}
	return &semver{Major: maj, Minor: min, Patch: patch, Prerelease: pre, Build: build, Original: orig}, nil
}

func (s *semver) String() string { return s.Original }

func (f *SemverFuncs) Semver(args ...any) (*semver, error) {
	if len(args) != 1 {
