	maj, err := strconv.Atoi(parts[0])
	if err != nil {
		return nil, err
	}
	min, err := strconv.Atoi(parts[1])
	if err != nil {
		return nil, err
	}
	patch, err := strconv.Atoi(parts[2])
	if err != nil {
		// patch may contain pre? Already split, but handle?
		return nil, err
	}
	return &semver{Major: maj, Minor: min, Patch: patch, Prerelease: pre, Build: build, Original: orig}, nil
}

func (s *semver) String() string { return s.Original }

func (f *SemverFuncs) Semver(args ...any) (*semver, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("wrong number of args for Semver: want 1 got %d", len(args))
	}
	return parseSemver(fmt.Sprintf("%v", args[0]))
}

func (f *SemverFuncs) CheckConstraint(args ...any) (bool, error) {
	if len(args) != 2 {
		return false, fmt.Errorf("wrong number of args for CheckConstraint: want 2 got %d", len(args))
	}
	constraint := fmt.Sprintf("%v", args[0])
	vers := fmt.Sprintf("%v", args[1])
	return checkConstraint(constraint, vers)
}

func checkConstraint(constraint, vers string) (bool, error) {
	v, err := parseSemver(vers)
	if err != nil {
		return false, err
	}
	// constraint can be comma-separated? Support simple: ">=1.0.0", ">1.0.0", "<2.0.0", "=1.2.3", "1.2.3", "~1.2", "^1.2.3", ">=1.0.0, <2.0.0" etc.
	parts := strings.Split(constraint, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		ok, err := checkSingle(p, v)
		if err != nil {
			return false, err
		}
		if !ok {
			return false, nil
		}
	}
	return true, nil
}

func checkSingle(c string, v *semver) (bool, error) {
	c = strings.TrimSpace(c)
	var op, verStr string
	for _, prefix := range []string{">=", "<=", "!=", ">", "<", "=", "~", "^", "=="} {
		if strings.HasPrefix(c, prefix) {
			op = prefix
			verStr = strings.TrimSpace(c[len(prefix):])
			break
		}
	}
	if op == "" {
		op = "="
		verStr = c
	}
	// handle ~ and ^ specially? Simplify: ~1.2.3 means >=1.2.3, <1.3.0 ; ^1.2.3 means >=1.2.3, <2.0.0
	if op == "~" || op == "^" {
		base, err := parseSemver(verStr)
		if err != nil {
			// try with partial? e.g., "~1.2" ?
			return false, err
		}
		if compare(v, base) < 0 {
			return false, nil
		}
		var upper *semver
		if op == "~" {
			upper = &semver{Major: base.Major, Minor: base.Minor+1, Patch: 0}
		} else {
			upper = &semver{Major: base.Major+1, Minor: 0, Patch: 0}
		}
		if compare(v, upper) >= 0 {
			return false, nil
		}
		return true, nil
	}
	cv, err := parseSemver(verStr)
	if err != nil {
		return false, err
	}
	cmp := compare(v, cv)
	switch op {
	case "=", "==":
		return cmp == 0, nil
	case "!=":
		return cmp != 0, nil
	case ">":
		return cmp > 0, nil
	case ">=":
		return cmp >= 0, nil
	case "<":
		return cmp < 0, nil
	case "<=":
		return cmp <= 0, nil
	}
	return false, fmt.Errorf("unknown operator %q", op)
}

func compare(a, b *semver) int {
	if a.Major != b.Major {
		if a.Major < b.Major {
			return -1
		}
		return 1
	}
	if a.Minor != b.Minor {
		if a.Minor < b.Minor {
			return -1
		}
		return 1
	}
	if a.Patch != b.Patch {
		if a.Patch < b.Patch {
			return -1
		}
		return 1
	}
	// prerelease? Release > prerelease? Simplify: if both have pre, compare lexically, if one has pre, it is smaller?
	if a.Prerelease == b.Prerelease {
		return 0
	}
	if a.Prerelease == "" {
		return 1
	}
	if b.Prerelease == "" {
		return -1
	}
	if a.Prerelease < b.Prerelease {
		return -1
	}
	return 1
}
