package funcs

import (
	"crypto/rand"
	"fmt"
	"strings"
)

type UUIDFuncs struct{}

func newUUID(variant int) string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	// version
	if variant == 1 {
		// version 1: time-based? Simplify: set version 1, variant 10xx
		b[6] = (b[6] & 0x0f) | 0x10
	} else {
		b[6] = (b[6] & 0x0f) | 0x40
	}
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func (f *UUIDFuncs) V1(args ...any) (string, error) {
	if len(args) != 0 {
		return "", fmt.Errorf("wrong number of args for V1: want 0 got %d", len(args))
	}
	return newUUID(1), nil
}

func (f *UUIDFuncs) V4(args ...any) (string, error) {
	if len(args) != 0 {
		return "", fmt.Errorf("wrong number of args for V4: want 0 got %d", len(args))
	}
	return newUUID(4), nil
}

func (f *UUIDFuncs) Nil(args ...any) (string, error) {
	if len(args) != 0 {
		return "", fmt.Errorf("wrong number of args for Nil: want 0 got %d", len(args))
	}
	return "00000000-0000-0000-0000-000000000000", nil
}

func (f *UUIDFuncs) IsValid(args ...any) (bool, error) {
	if len(args) != 1 {
		return false, fmt.Errorf("wrong number of args for IsValid: want 1 got %d", len(args))
	}
	s := fmt.Sprintf("%v", args[0])
	return isValidUUID(s), nil
}

func isValidUUID(s string) bool {
	if len(s) != 36 {
		return false
	}
	for i, c := range s {
		if i == 8 || i == 13 || i == 18 || i == 23 {
			if c != '-' {
				return false
			}
		} else {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return false
			}
		}
	}
	return true
}

func (f *UUIDFuncs) Parse(args ...any) (string, error) {
	if len(args) != 1 {
		return "", fmt.Errorf("wrong number of args for Parse: want 1 got %d", len(args))
	}
	s := strings.ToLower(fmt.Sprintf("%v", args[0]))
	if !isValidUUID(s) {
		return "", fmt.Errorf("invalid UUID %q", s)
	}
	return s, nil
}
