	}
	// CIDRHost cidr hostNum? Experimental. Implement simple: parse CIDR, add hostNum to network?
	cidr := fmt.Sprintf("%v", args[0])
	var hostNum int
	switch v := args[1].(type) {
	case int:
		hostNum = v
	case int64:
		hostNum = int(v)
	default:
		return "", fmt.Errorf("invalid host number")
	}
	_, ipnet, err := net.ParseCIDR(cidr)
	if err != nil {
		return "", err
	}
	ip := ipnet.IP.To4()
	if ip == nil {
		return "", fmt.Errorf("only IPv4 supported")
	}
	// Add hostNum
	val := uint32(ip[0])<<24 | uint32(ip[1])<<16 | uint32(ip[2])<<8 | uint32(ip[3])
	val += uint32(hostNum)
	out := net.IPv4(byte(val>>24), byte(val>>16), byte(val>>8), byte(val))
