func logError(stderr io.Writer, msg string) {
	format := os.Getenv("GOMPLATE_LOG_FORMAT")
	switch format {
	case "logfmt":
		fmt.Fprintf(stderr, "time=%s level=ERROR msg=\"\" err=%q\n", time.Now().UTC().Format("2006-01-02T15:04:05.000Z"), msg)
	case "console":
		fmt.Fprintf(stderr, "%s ERR  err=%q\n", time.Now().Format("15:04:05"), msg)
	case "simple":
		fmt.Fprintf(stderr, "   err=%q\n", msg)
	default:
		fmt.Fprintf(stderr, "{\"time\":\"%s\",\"level\":\"ERROR\",\"msg\":\"\",\"err\":%q}\n", time.Now().UTC().Format(time.RFC3339Nano), msg)
	}
}

func logDebug(stderr io.Writer, msg string, fields map[string]any) {
	format := os.Getenv("GOMPLATE_LOG_FORMAT")
	switch format {
	case "logfmt":
		// time=... level=DEBUG msg="..." version=... build=... etc.
		ts := time.Now().UTC().Format("2006-01-02T15:04:05.000Z")
		fmt.Fprintf(stderr, "time=%s level=DEBUG msg=%q", ts, msg)
		for k, v := range fields {
			fmt.Fprintf(stderr, " %s=%v", k, formatLogfmtVal(v))
		}
		fmt.Fprint(stderr, "\n")
	case "console":
		ts := time.Now().Format("15:04:05")
		// console: "09:09:45 DBG starting gomplate\n09:09:45 DBG config is:\n---\nin: hi\n version=... build=... \n"
		// For config is, msg contains newlines, need to handle?
		if strings.Contains(msg, "config is:") {
			fmt.Fprintf(stderr, "%s DBG %s", ts, msg)
			// fields version/build?
			if v, ok := fields["version"]; ok {
				fmt.Fprintf(stderr, " version=%v", v)
			}
			if b, ok := fields["build"]; ok {
				fmt.Fprintf(stderr, " build=%v", b)
			}
			fmt.Fprint(stderr, "\n")
		} else if strings.Contains(msg, "completed rendering") {
			fmt.Fprintf(stderr, "%s DBG %s", ts, msg)
			for k, v := range fields {
				fmt.Fprintf(stderr, " %s=%v", k, v)
			}
			fmt.Fprint(stderr, "\n")
		} else {
			fmt.Fprintf(stderr, "%s DBG %s", ts, msg)
			for k, v := range fields {
				fmt.Fprintf(stderr, " %s=%v", k, v)
			}
			fmt.Fprint(stderr, "\n")
		}
	case "simple":
		// "  starting gomplate\n  config is:\n---\nin: hi\n version=... build=... \n"
		fmt.Fprintf(stderr, "  %s", msg)
		if len(fields) > 0 {
			// for config is, fields version/build on same line? Actually simple: "  config is:\n---\nin: hi\n version=0.0.0 build=HEAD\n"
			// msg already contains "config is:\n---\nin: hi\n", then fields?
			for k, v := range fields {
				fmt.Fprintf(stderr, " %s=%v", k, v)
			}
		}
		fmt.Fprint(stderr, "\n")
	default:
		// json
		m := map[string]any{
			"time":  time.Now().UTC().Format(time.RFC3339Nano),
			"level": "DEBUG",
			"msg":   msg,
		}
		for k, v := range fields {
			m[k] = v
		}
		b, _ := json.Marshal(m)
		fmt.Fprintf(stderr, "%s\n", string(b))
	}
}

func formatLogfmtVal(v any) string {
	switch x := v.(type) {
	case string:
		if strings.Contains(x, " ") || strings.Contains(x, "\n") || strings.Contains(x, `"`) {
			return fmt.Sprintf("%q", x)
		}
		return x
	default:
		return fmt.Sprintf("%v", v)
	}
}

func logInfoExperimental(stderr io.Writer) {
	format := os.Getenv("GOMPLATE_LOG_FORMAT")
	msg := "experimental functions and features enabled!"
	switch format {
	case "logfmt":
		fmt.Fprintf(stderr, "time=%s level=INFO msg=%q experimental=true\n", time.Now().UTC().Format("2006-01-02T15:04:05.000Z"), msg)
	case "console":
		fmt.Fprintf(stderr, "%s INF %s experimental=true\n", time.Now().Format("15:04:05"), msg)
	case "simple":
		fmt.Fprintf(stderr, "  %s experimental=true\n", msg)
	default:
		fmt.Fprintf(stderr, "{\"time\":\"%s\",\"level\":\"INFO\",\"msg\":%q,\"experimental\":true}\n", time.Now().UTC().Format(time.RFC3339Nano), msg)
	}
}

