func validateHeader(s string) error {
	// format alias=Name: value
	eq := strings.Index(s, "=")
	if eq < 0 {
		return fmt.Errorf("invalid datasource-header option '%s'", s)
	}
	rest := s[eq+1:]
	colon := strings.Index(rest, ":")
	if colon < 0 {
		return fmt.Errorf("invalid datasource-header option '%s'", s)
	}
	return nil
}

