func quoteSlice(s []string) []string {
	out := make([]string, len(s))
	for i, v := range s {
		// original dump uses ['-'] with single quotes, and [/tmp/in.tmpl] without quotes? Check: inputFiles: [/tmp/in.tmpl] (no quotes), outputFiles: ['-'] (quotes for -). So quoting depends? For paths with special chars, quote? Simplify: if v == "-" then "'-'", else v as is? But what about paths with spaces? Probably quote? For simplicity, if v contains special, quote with single? We'll implement: if v == "-" then "'-'", else v.
		if v == "-" {
