func parseDatasourceArg(s string) (string, string) {
	eq := strings.Index(s, "=")
	if eq < 0 {
		// no =, infer alias from file name? e.g., "person.json" => alias "person", url "person.json"
		// For dump, need to show alias and url? Our cfg.Datasources for implicit alias stores as single string without =? Actually parseArgs for -d without =? We currently treat -d value as whole string without splitting? In parseArgs, we do cfg.Datasources = append(..., val) where val is whole arg (e.g., "person.json"). For dump, we need to parse it to alias+url. So handle here.
		// Infer alias: base without extension?
		base := filepath.Base(s)
		ext := filepath.Ext(base)
		alias := strings.TrimSuffix(base, ext)
		if alias == "" {
			alias = s
		}
		return alias, s
	}
	return s[:eq], s[eq+1:]
}

func parseHeader(s string) (alias, name, val string) {
	eq := strings.Index(s, "=")
	if eq < 0 {
		return "", "", ""
	}
	alias = s[:eq]
	rest := s[eq+1:]
	colon := strings.Index(rest, ":")
	if colon < 0 {
		return alias, "", ""
	}
	name = strings.TrimSpace(rest[:colon])
	val = strings.TrimSpace(rest[colon+1:])
	return alias, name, val
}

