func parseEnvFile(s string) (map[string]string, error) {
	m := make(map[string]string)
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "export ") {
			line = strings.TrimSpace(line[7:])
		}
		eq := strings.Index(line, "=")
		if eq < 0 {
			continue
		}
		k := strings.TrimSpace(line[:eq])
		v := strings.TrimSpace(line[eq+1:])
		// handle quotes?
		if len(v) >= 2 && ((v[0] == '"' && v[len(v)-1] == '"') || (v[0] == '\'' && v[len(v)-1] == '\'')) {
			if v[0] == '"' {
				// double-quoted: handle escapes and variable expansion?
				inner := v[1 : len(v)-1]
				inner = strings.ReplaceAll(inner, `\n`, "\n")
				inner = strings.ReplaceAll(inner, `\t`, "\t")
				inner = strings.ReplaceAll(inner, `\"`, `"`)
				inner = strings.ReplaceAll(inner, `\\`, `\`)
				// variable expansion: ${FOO} or $FOO? Use os.ExpandEnv with current m? For simplicity, expand with os env + m?
				// We'll expand ${VAR} using m and os env
				inner = expandEnvWithMap(inner, m)
				v = inner
			} else {
				v = v[1 : len(v)-1]
			}
		} else {
			// unquoted: trim? Variable expansion?
			v = expandEnvWithMap(v, m)
		}
		// key may contain .? Like FOO.BAR? Keep as is.
		m[k] = v
	}
	return m, nil
}

func expandEnvWithMap(s string, m map[string]string) string {
	// expand $VAR and ${VAR} using m and os env
	return os.Expand(s, func(key string) string {
		if v, ok := m[key]; ok {
			return v
		}
		return os.Getenv(key)
	})
}

