func toFloatMain(v any) (float64, error) {
	switch n := v.(type) {
	case int:
		return float64(n), nil
	case int64:
		return float64(n), nil
	case float64:
		return n, nil
	case string:
		return strconv.ParseFloat(n, 64)
	default:
		return 0, fmt.Errorf("invalid number")
	}
}
func isIntMain(v any) bool {
	switch v.(type) {
	case int, int64:
		return true
	default:
		return false
	}
}

