	if len(args) < 1 || len(args) > 3 {
		return "", fmt.Errorf("wrong number of args for tpl: want 1, 2, or 3 - got %d", len(args))
	}
	var tplStr string
	var ctx any = CurrentCtx
	if len(args) == 1 {
		tplStr = fmt.Sprintf("%v", args[0])
	} else if len(args) == 2 {
		tplStr = fmt.Sprintf("%v", args[0])
		ctx = args[1]
	} else {
		tplStr = fmt.Sprintf("%v", args[0])
		ctx = args[1]
	}
	left := "{{"
	right := "}}"
	if v, ok := CurrentCfg["left"]; ok {
		left = v
	}
	if v, ok := CurrentCfg["right"]; ok {
		right = v
	}
	missing := "error"
	if v, ok := CurrentCfg["missing"]; ok {
		missing = v
	}
	tmpl, err := template.New("inline").Option("missingkey=" + missing).Funcs(CurrentFuncMap).Delims(left, right).Parse(tplStr)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, ctx); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (t *Template) Path(args ...any) (string, error) {
	if len(args) != 0 {
		return "", fmt.Errorf("wrong number of args for Path: want 0 got %d", len(args))
	}
	if CurrentName == "<stdin>" {
		return "<arg>", nil
	}
	if CurrentName == "" {
		return "<arg>", nil
	}
	return CurrentName, nil
}

func (t *Template) PathDir(args ...any) (string, error) {
	if len(args) != 0 {
		return "", fmt.Errorf("wrong number of args for PathDir: want 0 got %d", len(args))
	}
	// For <arg> or <stdin>, return "."? Test showed PathDir for -i gives "." Good.
	if CurrentName == "<arg>" || CurrentName == "<stdin>" || CurrentName == "" {
		return ".", nil
	}
	// For file path, return dir?
	// Use path.Dir? For "/tmp/foo.tmpl", dir is "/tmp"? For relative?
	// Simplify: find last /?
	for i := len(CurrentName) - 1; i >= 0; i-- {
		if CurrentName[i] == '/' {
			if i == 0 {
				return "/", nil
			}
			return CurrentName[:i], nil
		}
	}
	return ".", nil
}
